INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DRAM dasselbe wie SRAM?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Technologien"}, {"text": "Ja", "correct": false, "because": "SRAM ist statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat DRAM?', 3, '[{"text": "Temporäre Datenspeicherung", "correct": true, "because": "Arbeitsspeicher"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Nicht wie SSD"}, {"text": "Grafikverarbeitung", "correct": false, "because": "GPU-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat DRAM?', 5, '[{"text": "Dynamische Aktualisierung", "correct": true, "because": "Refresh nötig"}, {"text": "Hohe Dichte", "correct": true, "because": "Mehr Speicher pro Chip"}, {"text": "Statische Speicherung", "correct": false, "because": "SRAM-Eigenschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DRAM ist flüchtig. b) Es speichert Daten dauerhaft.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verliert Daten ohne Strom"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DRAM?', 4, '[{"text": "Refresh-Rate", "correct": false, "because": "Für Funktion nötig"}, {"text": "Kapazität", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DRAM ständig aktualisiert werden muss?', 2, '[{"text": "Ja", "correct": true, "because": "Dynamisches Refresh"}, {"text": "Nein", "correct": false, "because": "Unterschied zu SRAM"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche DRAM-Variante ist für PCs üblich?', 3, '[{"text": "DDR-DRAM", "correct": true, "because": "Double Data Rate"}, {"text": "SRAM", "correct": false, "because": "Statischer Speicher"}, {"text": "Flash", "correct": false, "because": "Dauerhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DRAM?', 5, '[{"text": "Hohe Speicherdichte", "correct": true, "because": "Platzsparend"}, {"text": "Günstige Produktion", "correct": true, "because": "Kosteneffizient"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Flüchtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DRAM ist schneller als SRAM. b) Es braucht regelmäßige Aktualisierung. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "SRAM ist schneller"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DRAM?', 4, '[{"text": "Stromversorgung", "correct": false, "because": "Für Refresh nötig"}, {"text": "Speichercontroller", "correct": false, "because": "Steuerung erforderlich"}, {"text": "Externer Akku", "correct": true, "because": "Mainboard reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DRAM langsamer als SRAM?', 2, '[{"text": "Ja", "correct": true, "because": "SRAM schneller"}, {"text": "Nein", "correct": false, "because": "SRAM hat Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften beeinflussen DRAM-Leistung?', 4, '[{"text": "Taktfrequenz", "correct": true, "because": "Schnelligkeit"}, {"text": "Latenzzeit", "correct": true, "because": "Zugriffszeit"}, {"text": "Gewicht", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DRAM nur für Laptops ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch PCs, Server"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DRAM?', 3, '[{"text": "Kapazität", "correct": true, "because": "Für Anwendungen nötig"}, {"text": "Optisches Design", "correct": false, "because": "Sekundär"}, {"text": "Niedriger Preis", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DRAM nutzt Kondensatoren. b) Es ist statisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dynamisch, nicht statisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche DRAM-Typen gibt es?', 5, '[{"text": "DDR4", "correct": true, "because": "Aktuelle Generation"}, {"text": "DDR5", "correct": true, "because": "Neueste Generation"}, {"text": "SRAM", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DRAM unwichtig?', 3, '[{"text": "Bandbreite", "correct": false, "because": "Leistungsfaktor"}, {"text": "Refresh-Zyklus", "correct": false, "because": "Funktion nötig"}, {"text": "Verpackung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss DRAM ständig mit Strom versorgt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Flüchtig"}, {"text": "Nein", "correct": false, "because": "Verliert Daten sonst"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DRAM teurer als SRAM ist?', 2, '[{"text": "Nein", "correct": true, "because": "Günstiger"}, {"text": "Ja", "correct": false, "because": "Kosteneffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für DRAM zentral?', 4, '[{"text": "Dynamisches Refresh", "correct": true, "because": "Speichererhalt"}, {"text": "Statische Speicherung", "correct": false, "because": "SRAM"}, {"text": "Dauerhafte Daten", "correct": false, "because": "Flüchtig"}]');
